    chip(W / 2, 255, 1500, 58, 'u_f = ∫₀^∞ Q_t f dt bounded  ⇒  P( |∫_a^(a+L₁) f(K_r) dr| > C √(L₁ x) )  ≤  C e^(−x) ,   f = c_i c_j − M_ij', C.cyan, q, 19);
    const sq = Q(S, 0, 'fluctuate only on the scale root L', 0.6) * f1;
    lblG('second moment ≤ C L₁ ;  under both exact laws , split at τ − 1', 520, 330, C.dim, sq, 17);
    const tq = Q(S, 0, 'a dyadic tree of Gaussian bridges', 0.6) * f1;
