      line(ax, ay, ax + aw, ay, C.dim, wq, 1.5); lbl('time', ax + aw, ay + 30, C.dim, wq, 15, 'right');
      fillBox(ax + 260, ay - 200, 300, 200, C.cyan, wq * 0.1); dashed(ax + 260, ay - 200, ax + 260, ay, C.cyan, wq, 1.4); dashed(ax + 560, ay - 200, ax + 560, ay, C.cyan, wq, 1.4);
      lbl('[a , a + L₁]', ax + 410, ay + 30, C.cyan, wq, 16);
      ctx.save(); ctx.globalAlpha = wq; ctx.strokeStyle = C.gold; ctx.lineWidth = 2.4; ctx.beginPath();
      for (let i = 0; i <= 240; i++) { const x = ax + i * aw / 240, y = ay - 100 + 60 * Math.tanh((WIG111[(i + 60) % 600] - WIG111[60]) / 4); if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y); }
      ctx.stroke(); ctx.restore();
      arrow(ax + 600, ay - 100, ax + 600, ay - 170, C.mag, wq, 2); arrow(ax + 600, ay - 100, ax + 600, ay - 30, C.mag, wq, 2);
      lbl('≈ C √(L₁ x)', ax + 615, ay - 95, C.mag, wq, 17, 'left');
